/**
 * Lesson / mission content format. Everything is plain JSON so lessons live in
 * `src/content` (and can later be generated by the content pipeline).
 */
import type { Disk, HttpResponse, PerfState, Process } from '../sim/state';
import type { ProjectSpec } from '../sim/forge/types';
import type { DnsRecord, RemoteHost } from '../sim/netsim/types';
import type { BinarySpec } from '../sim/systemd/types';
import type { AppSpec } from '../sim/kube/types';

export type BranchId =
  // theory tracks (knowledge checks)
  | 'foundations'
  | 'networking'
  | 'storage-databases'
  | 'system-design'
  | 'sre'
  // hands-on tracks
  | 'linux-basics'
  | 'files-permissions'
  | 'processes'
  | 'text-processing'
  | 'docker-basics'
  | 'images-dockerfile'
  | 'volumes-networks'
  | 'compose'
  | 'troubleshooting'
  | 'systemd'
  | 'network-tools'
  | 'performance'
  // planned
  | 'version-control'
  | 'git-branching'
  | 'git-remotes'
  | 'kubernetes'
  | 'k8s-networking'
  | 'k8s-troubleshooting'
  | 'k8s-storage'
  | 'k8s-scheduling'
  | 'k8s-traffic'
  | 'k8s-rbac-helm'
  | 'cicd'
  | 'cicd-gitlab'
  | 'deploy-strategies'
  | 'gitops'
  | 'cloud-iac'
  | 'observability'
  | 'security';

export interface Lesson {
  id: string;
  title: string;
  branch: BranchId;
  /** Lesson ids that must be completed first. */
  prerequisites: string[];
  /** Short markdown shown before the missions. */
  theory: string;
  /** Notes in the learner's knowledge vault this lesson is based on (e.g. "02-Networking/02-DNS"). */
  sources?: string[];
  missions: Mission[];
}

/** `quiz` missions are knowledge checks answered in the lesson pane (no terminal). */
export type MissionType = 'guided' | 'free' | 'boss' | 'quiz';

export type Question =
  | { kind: 'single'; prompt: string; options: string[]; answer: number; explain?: string }
  | { kind: 'multi'; prompt: string; options: string[]; answers: number[]; explain?: string }
  | { kind: 'number'; prompt: string; answer: number; tolerance?: number; unit?: string; explain?: string }
  /** `items` are listed in the correct order; the UI shuffles them. */
  | { kind: 'order'; prompt: string; items: string[]; explain?: string }
  /** Accepted answers: case-insensitive exact strings, or `/regex/`. */
  | { kind: 'text'; prompt: string; accept: string[]; explain?: string };

export interface Mission {
  id: string;
  title: string;
  type: MissionType;
  /** Markdown task description. */
  prompt: string;
  initialState?: InitialStateSpec;
  /** Progressive hints, revealed one at a time. Free and boss missions may have none. */
  hints: Hint[];
  validator: Validator;
  xp: number;
  /** Expected number of commands for an efficient solution. */
  par: number;
  /** Markdown shown after success: why the solution works. */
  explain?: string;
  /** A reference solution, one command line per entry. Used by content QA tests. */
  solution: string[];
  /** Knowledge-check questions (quiz missions only). */
  questions?: Question[];
}

export interface Hint {
  text: string;
  /** XP deducted from the mission reward when revealed. */
  cost: number;
}

export interface Validator {
  /** All must pass for the mission to succeed. */
  checks: Check[];
  /**
   * Conditions that must stay true throughout (e.g. "don't delete the config").
   * Breaking one counts as a destructive mistake.
   */
  guards?: Check[];
}

/** Every check can override the feedback shown when it fails. */
interface CheckBase {
  message?: string;
}

export type Check = CheckBase &
  (
    | { type: 'fileExists'; path: string; kind?: 'file' | 'dir' }
    | { type: 'fileMissing'; path: string }
    | { type: 'fileContains'; path: string; text?: string; regex?: string; equals?: string }
    | { type: 'fileMode'; path: string; mode: string }
    | { type: 'fileOwner'; path: string; owner?: string; group?: string }
    | { type: 'cwd'; path: string }
    | { type: 'varEquals'; name: string; value: string; exported?: boolean }
    | { type: 'processRunning'; match: string }
    | { type: 'processAbsent'; match: string }
    /** A command (argv[0]) was run, optionally with these arguments and successfully. */
    | { type: 'commandUsed'; command: string; argsInclude?: string[]; succeeded?: boolean }
    /** Some command's stdout (since the mission started) contained this text / regex. */
    | { type: 'outputContains'; text?: string; regex?: string }
    | { type: 'anyOf'; checks: Check[] }
    | { type: 'not'; check: Check }
    // ---- Docker
    /** A running container, matched by name and/or image reference. */
    | { type: 'containerRunning'; name?: string; image?: string }
    | { type: 'containerAbsent'; name: string }
    /** Running container `name` publishes hostPort (optionally → containerPort). */
    | { type: 'containerPort'; name: string; hostPort: number; containerPort?: number }
    /** `KEY=VALUE`, or just `KEY` to require that it is set. */
    | { type: 'containerEnv'; name: string; env: string }
    | { type: 'containerMount'; name: string; target: string; source?: string; mountType?: 'volume' | 'bind' }
    | { type: 'containerNetwork'; name: string; network: string }
    /** Compare a `docker inspect` field (dotted path) to a value. */
    | { type: 'containerInspect'; name: string; path: string; equals: string }
    /** A file inside a container's filesystem. */
    | { type: 'containerFile'; name: string; path: string; text?: string; regex?: string }
    | { type: 'imageExists'; ref: string }
    | { type: 'imageInspect'; ref: string; path: string; equals: string }
    | { type: 'volumeExists'; name: string }
    | { type: 'networkExists'; name: string }
    /** A request from the host (like curl) succeeds, optionally containing text / with a status. */
    | { type: 'httpResponds'; url: string; contains?: string; status?: number }
    // ---- systemd / host
    /** A systemd unit is in this state (default "active"). */
    | { type: 'serviceActive'; unit: string; state?: 'active' | 'inactive' | 'failed' }
    | { type: 'serviceEnabled'; unit: string; enabled?: boolean }
    /** `df` Use% of the filesystem holding `mount` is below `percent`. */
    | { type: 'diskUsageBelow'; mount: string; percent: number }
    /** `df -i` IUse% of the filesystem holding `mount` is below `percent`. */
    | { type: 'inodeUsageBelow'; mount: string; percent: number }
    // ---- Git (paths are working-tree roots)
    | { type: 'gitRepo'; path: string }
    | { type: 'gitBranch'; path: string; name: string; exists?: boolean }
    | { type: 'gitHead'; path: string; branch: string }
    /** Nothing staged or modified, no conflict or merge/rebase in progress (untracked: false also forbids untracked files). */
    | { type: 'gitClean'; path: string; untracked?: boolean }
    /** A commit reachable from `ref` (default HEAD) whose message matches `pattern`; tipOnly: the ref's own commit. */
    | { type: 'gitCommit'; path: string; ref?: string; pattern: string; tipOnly?: boolean }
    /** File content as committed at `ref` (default HEAD). */
    | { type: 'gitFile'; path: string; ref?: string; file: string; text?: string; regex?: string; absent?: boolean }
    | { type: 'gitHistory'; path: string; ref?: string; count?: number; minCount?: number; linear?: boolean; minMerges?: number }
    /** Tracked = in the index; tracked: false = neither in the index nor in HEAD. */
    | { type: 'gitTracked'; path: string; file: string; tracked?: boolean }
    /** A simulated remote: a branch (default main) with commits / file content, or a tag. */
    | {
        type: 'gitRemote';
        url: string;
        branch?: string;
        tag?: string;
        /** Regex a commit message on the branch must match. */
        pattern?: string;
        file?: string;
        text?: string;
        regex?: string;
        absent?: boolean;
        linear?: boolean;
        exists?: boolean;
      }
    | { type: 'gitStash'; path: string; count: number }
    // ---- Kubernetes (namespace defaults to "default")
    /** An object exists (or not); `path` (dotted, e.g. spec.replicas) compared to `equals` / `regex`. */
    | { type: 'kubeResource'; kind: string; name: string; namespace?: string; exists?: boolean; path?: string; equals?: string; regex?: string }
    /** Pods matching a label selector ("app=web"): at least `ready` Ready, all Ready, a STATUS, no crash loop. */
    | { type: 'kubePods'; selector: string; namespace?: string; ready?: number; allReady?: boolean; status?: string; maxRestarts?: number; node?: string; notNode?: string }
    /** A Deployment is fully rolled out (all replicas updated and available), optionally with this image. */
    | { type: 'kubeRollout'; name: string; namespace?: string; image?: string; replicas?: number }
    | { type: 'kubeEndpoints'; service: string; namespace?: string; min?: number }
    /** A request through a Service (as from another pod) succeeds. */
    | {
        type: 'kubeHttp';
        service: string;
        namespace?: string;
        port?: number;
        path?: string;
        contains?: string;
        /** Send it from a pod matching this label selector (NetworkPolicies apply). */
        fromSelector?: string;
        fromNamespace?: string;
        /** Expect the request to fail (e.g. blocked by a NetworkPolicy). */
        blocked?: boolean;
      }
    /** A request through the ingress-nginx controller for this Host (and path) returns `status` (default: < 400) / contains text. */
    | { type: 'kubeIngress'; host: string; path?: string; status?: number; contains?: string; headers?: Record<string, string> }
    /**
     * The latest CI run (GitHub Actions workflow or GitLab pipeline) on a hosted repo, filtered by
     * workflow / branch / event: its conclusion, a job's result. By default it must be for the
     * branch's current head commit and finished.
     */
    | { type: 'ciRun'; repo: string; workflow?: string; branch?: string; event?: string; status?: string; job?: string; jobStatus?: string; anyCommit?: boolean; minRuns?: number }
    /** An image in the registry; `{sha}` / `{short}` / `{short8}` in `ref` stand for the head commit of `repo` (`branch`, default main). */
    | { type: 'registryImage'; ref: string; repo?: string; branch?: string; exists?: boolean }
    /** An Argo CD Application's sync / health status; `atHead` = synced to the current head of its repo's branch. */
    | { type: 'argoApp'; name: string; namespace?: string; sync?: string; health?: string; atHead?: string; automated?: boolean; prune?: boolean; selfHeal?: boolean; exists?: boolean }
    /** A file inside the volume bound to a PersistentVolumeClaim (data that outlives pods). */
    | { type: 'kubeVolumeFile'; claim: string; namespace?: string; path: string; contains?: string }
    /** RBAC: `kubectl auth can-i VERB RESOURCE --as AS [-n NS]` answers `allowed`. */
    | { type: 'kubeCanI'; as: string; verb: string; resource: string; namespace?: string; allowed: boolean }
    /** A Helm release: its latest revision's status (default deployed), revision, chart version, or a computed value. */
    | { type: 'helmRelease'; name: string; namespace?: string; status?: string; minRevision?: number; chartVersion?: string; path?: string; equals?: string; exists?: boolean }
  );

export type CheckType = Check['type'];

export interface FileSpec {
  /** File content; omit (with type "dir") for directories. */
  content?: string;
  type?: 'file' | 'dir';
  /** Octal string, e.g. "644". */
  mode?: string;
  owner?: string;
  group?: string;
  /** Apparent size in bytes (for huge log files) — content stays small. */
  size?: number;
}

/** A compact description of how a mission's machine differs from the default one. */
export interface InitialStateSpec {
  user?: string;
  /** Working directory; defaults to the user's home. */
  cwd?: string;
  /** Paths to create or overwrite. Parent directories are created automatically. */
  files?: Record<string, string | FileSpec>;
  /** Paths to delete from the default filesystem. */
  remove?: string[];
  /** Variables to set (and export). */
  env?: Record<string, string>;
  /** Extra processes. Missing fields get sensible defaults. */
  processes?: (Partial<Process> & { pid: number; command: string })[];
  network?: Record<string, HttpResponse>;
  /**
   * Shell commands run (as the learner) after files are created — e.g. `docker run ...`
   * to start from a pre-built or deliberately broken setup. Each must exit 0
   * (append `|| true` for commands that are meant to fail).
   */
  setup?: string[];
  /** Many similar files at once: `${dir}/${prefix}${n}` for n = 1..count (e.g. session files). */
  bulkFiles?: { dir: string; prefix: string; count: number; content?: string; owner?: string }[];
  /** Behaviour of simulated programs that systemd can run, by executable path. */
  binaries?: Record<string, BinarySpec>;
  /** Extra DNS records (added to the default zone data). */
  dns?: DnsRecord[];
  /** Extra remote hosts reachable over the network. */
  remotes?: RemoteHost[];
  /** Load / memory / CPU figures. */
  perf?: Partial<PerfState>;
  /** Overrides for existing filesystems (matched by mount point) or new ones. */
  disks?: (Partial<Disk> & { mount: string })[];
  /**
   * Hosted Git remotes (e.g. https://github.com/acme/shop.git), created empty before `setup`
   * runs so setup commands can clone and push to them. `protected` branches refuse direct pushes.
   */
  gitHosted?: {
    url: string;
    branch?: string;
    protected?: string[];
    /** Initial commit content (path → text); `message` is its commit message. */
    files?: Record<string, string>;
    message?: string;
  }[];
  /** Hosting-platform settings per hosted repo URL: secrets, variables, environments, runner tags. */
  forge?: Record<
    string,
    {
      secrets?: Record<string, string>;
      variables?: Record<string, string | { value: string; protected?: boolean; masked?: boolean; file?: boolean }>;
      environments?: Record<string, { secrets?: Record<string, string> }>;
      runnerTags?: string[];
    }
  >;
  /** How each project's simulated npm toolchain behaves (tests, lint, build), by package name. */
  projects?: Record<string, ProjectSpec>;
  /** Image references already in the registry (e.g. pushed by earlier CI runs). */
  registryImages?: string[];
  /** Install Argo CD into the cluster (namespace argocd, Application CRDs). */
  argocd?: boolean;
  /** Argo CD Applications to create once it is installed (YAML). */
  argoApps?: string;
  /** Mission-defined container images in the cluster registry, by reference. */
  kubeImages?: Record<string, AppSpec>;
  /** YAML applied to the cluster before setup (hidden from the learner). */
  kubeManifests?: string;
  /** Extra CPU demand (millicores) on workloads, "namespace/deployment" → m (traffic for HPA missions). */
  kubeLoad?: Record<string, number>;
  /** Simulated seconds that pass after setup (so containers look "Up 5 minutes"). Default 300. */
  setupAge?: number;
}
